window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-52050a72c7f4a6b1"]={"versions": [{"id": "FIG-52050a72c7f4a6b1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Initialisierungsablaufs des FlexRay-Netzwerkmanagements im Kontext der AUTOSAR Classic Platform (Communication Stack / System Services). Dargestellt ist die synchrone Interaktion zwischen dem übergeordneten Network Management Interface (<code>Nm</code>) und dem BSW-Modul <code>FrNm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lebenslinien:</strong></li>\n<li><code>«module» Nm</code>: Generische Netzwerkmanagement-Schnittstelle (Aufrufer).</li>\n<li><code>«module» FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul (Aufgerufener / Zielinstanz).</li>\n<li><strong>Zustandssymbol:</strong></li>\n<li><code>Bus Sleep Mode</code>: Zustand des FlexRay-Netzwerkmanagements, der der Lebenslinie von <code>FrNm</code> nach oder mit Abschluss der Initialisierung zugeordnet ist.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li>Aufruf: <code>FrNm_Init(nmConfigPtr)</code> (synchroner Funktionsaufruf mit Zeiger auf Konfigurationsstruktur).</li>\n<li>Rückkehr: <code>FrNm_Init()</code> (Return-Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Lebenslinie <code>Nm</code> stößt synchron den Initialisierungsaufruf <code>FrNm_Init(nmConfigPtr)</code> an die Lebenslinie <code>FrNm</code> an.</li>\n<li><code>FrNm</code> aktiviert seinen Ausführungsfokus, initialisiert die Modulressourcen anhand der übergebenen Konfigurationsdaten <code>nmConfigPtr</code> und nimmt den Modus <code>Bus Sleep Mode</code> ein.</li>\n<li>Nach Abschluss der Initialisierungsroutine kehrt der Kontrollfluss via <code>FrNm_Init()</code> synchron an das Modul <code>Nm</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Aufruf von <code>FrNm_Init</code> ist synchron auszuführen; Parameterübergabe erfolgt über den Konfigurationszeiger <code>nmConfigPtr</code>.</li>\n<li>Nach der Initialisierung befindet sich <code>FrNm</code> im Zustand <code>Bus Sleep Mode</code>.</li>\n<li>Das Modul <code>Nm</code> fungiert als koordinierende Instanz, die den Initialisierungsvorgang des BSW-Treibers bzw. -Moduls anstößt.</li>\n</ul>"}, {"id": "FIG-19a9027f6b6b5f5e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Initialisierungsablaufs des FlexRay-Netzwerkmanagements im Kontext der AUTOSAR Classic Platform (Communication Stack / System Services). Dargestellt ist die synchrone Interaktion zwischen dem übergeordneten Network Management Interface (<code>Nm</code>) und dem BSW-Modul <code>FrNm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lebenslinien:</strong></li>\n<li><code>«module» Nm</code>: Generische Netzwerkmanagement-Schnittstelle (Aufrufer).</li>\n<li><code>«module» FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul (Aufgerufener / Zielinstanz).</li>\n<li><strong>Zustandssymbol:</strong></li>\n<li><code>Bus Sleep Mode</code>: Zustand des FlexRay-Netzwerkmanagements, der der Lebenslinie von <code>FrNm</code> nach oder mit Abschluss der Initialisierung zugeordnet ist.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li>Aufruf: <code>FrNm_Init(nmConfigPtr)</code> (synchroner Funktionsaufruf mit Zeiger auf Konfigurationsstruktur).</li>\n<li>Rückkehr: <code>FrNm_Init()</code> (Return-Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Lebenslinie <code>Nm</code> stößt synchron den Initialisierungsaufruf <code>FrNm_Init(nmConfigPtr)</code> an die Lebenslinie <code>FrNm</code> an.</li>\n<li><code>FrNm</code> aktiviert seinen Ausführungsfokus, initialisiert die Modulressourcen anhand der übergebenen Konfigurationsdaten <code>nmConfigPtr</code> und nimmt den Modus <code>Bus Sleep Mode</code> ein.</li>\n<li>Nach Abschluss der Initialisierungsroutine kehrt der Kontrollfluss via <code>FrNm_Init()</code> synchron an das Modul <code>Nm</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Aufruf von <code>FrNm_Init</code> ist synchron auszuführen; Parameterübergabe erfolgt über den Konfigurationszeiger <code>nmConfigPtr</code>.</li>\n<li>Nach der Initialisierung befindet sich <code>FrNm</code> im Zustand <code>Bus Sleep Mode</code>.</li>\n<li>Das Modul <code>Nm</code> fungiert als koordinierende Instanz, die den Initialisierungsvorgang des BSW-Treibers bzw. -Moduls anstößt.</li>\n</ul>"}, {"id": "FIG-36369ccde3969e27", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Initialisierungsablaufs des FlexRay-Netzwerkmanagements im Kontext der AUTOSAR Classic Platform (Communication Stack / System Services). Dargestellt ist die synchrone Interaktion zwischen dem übergeordneten Network Management Interface (<code>Nm</code>) und dem BSW-Modul <code>FrNm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lebenslinien:</strong></li>\n<li><code>«module» Nm</code>: Generische Netzwerkmanagement-Schnittstelle (Aufrufer).</li>\n<li><code>«module» FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul (Aufgerufener / Zielinstanz).</li>\n<li><strong>Zustandssymbol:</strong></li>\n<li><code>Bus Sleep Mode</code>: Zustand des FlexRay-Netzwerkmanagements, der der Lebenslinie von <code>FrNm</code> nach oder mit Abschluss der Initialisierung zugeordnet ist.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li>Aufruf: <code>FrNm_Init(nmConfigPtr)</code> (synchroner Funktionsaufruf mit Zeiger auf Konfigurationsstruktur).</li>\n<li>Rückkehr: <code>FrNm_Init()</code> (Return-Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Lebenslinie <code>Nm</code> stößt synchron den Initialisierungsaufruf <code>FrNm_Init(nmConfigPtr)</code> an die Lebenslinie <code>FrNm</code> an.</li>\n<li><code>FrNm</code> aktiviert seinen Ausführungsfokus, initialisiert die Modulressourcen anhand der übergebenen Konfigurationsdaten <code>nmConfigPtr</code> und nimmt den Modus <code>Bus Sleep Mode</code> ein.</li>\n<li>Nach Abschluss der Initialisierungsroutine kehrt der Kontrollfluss via <code>FrNm_Init()</code> synchron an das Modul <code>Nm</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Aufruf von <code>FrNm_Init</code> ist synchron auszuführen; Parameterübergabe erfolgt über den Konfigurationszeiger <code>nmConfigPtr</code>.</li>\n<li>Nach der Initialisierung befindet sich <code>FrNm</code> im Zustand <code>Bus Sleep Mode</code>.</li>\n<li>Das Modul <code>Nm</code> fungiert als koordinierende Instanz, die den Initialisierungsvorgang des BSW-Treibers bzw. -Moduls anstößt.</li>\n</ul>"}, {"id": "FIG-3e72ef664d858b20", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Initialisierungsablaufs des FlexRay-Netzwerkmanagements im Kontext der AUTOSAR Classic Platform (ECU State Management / Communication Stack). Dargestellt ist die synchrone Initialisierungssequenz zwischen dem ECU State Manager (<code>EcuM</code>) und dem BSW-Modul <code>FrNm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lebenslinien:</strong></li>\n<li><code>«module» EcuM</code>: ECU State Manager als zentrale Zustands- und Startsteuerungsinstanz der Basissoftware (Aufrufer).</li>\n<li><code>«module» FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul (Aufgerufener / Zielinstanz).</li>\n<li><strong>Zustandssymbol:</strong></li>\n<li><code>Bus Sleep Mode</code>: Zielzustand des FlexRay-Netzwerkmanagements an der Lebenslinie von <code>FrNm</code>.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li>Aufruf: <code>FrNm_Init(nmConfigPtr)</code> (synchroner Funktionsaufruf mit Konfigurationszeiger).</li>\n<li>Rückkehr: <code>FrNm_Init()</code> (Rückkehr-Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>EcuM</code> ruft während der BSW-Initialisierungsphase synchron die Funktion <code>FrNm_Init(nmConfigPtr)</code> am Modul <code>FrNm</code> auf.</li>\n<li><code>FrNm</code> aktiviert den internen Ausführungsfokus, verarbeitet die übergebene Konfiguration <code>nmConfigPtr</code> und etabliert den Ausgangszustand <code>Bus Sleep Mode</code>.</li>\n<li>Mit Abschluss der Initialisierungslogik kehrt die Steuerung über den Rückkehrpfad <code>FrNm_Init()</code> synchron an den <code>EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Initialisierung von <code>FrNm</code> wird durch den <code>EcuM</code> angestoßen (typischerweise im Rahmen der BSW-Init-Sequenzen/Init-Listen).</li>\n<li>Als initialer Zustand nach Aufruf von <code>FrNm_Init</code> ist <code>Bus Sleep Mode</code> vorgeschrieben.</li>\n<li>Die Übergabe der Konfiguration erfolgt zwingend über den Zeiger <code>nmConfigPtr</code>.</li>\n</ul>"}, {"id": "FIG-32edec8e1dd1e51c", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Initialisierungsablaufs des FlexRay-Netzwerkmanagements im Kontext der AUTOSAR Classic Platform (ECU State Management / Communication Stack). Dargestellt ist die synchrone Initialisierungssequenz zwischen dem ECU State Manager (<code>EcuM</code>) und dem BSW-Modul <code>FrNm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lebenslinien:</strong></li>\n<li><code>«module» EcuM</code>: ECU State Manager als zentrale Zustands- und Startsteuerungsinstanz der Basissoftware (Aufrufer).</li>\n<li><code>«module» FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul (Aufgerufener / Zielinstanz).</li>\n<li><strong>Zustandssymbol:</strong></li>\n<li><code>Bus Sleep Mode</code>: Zielzustand des FlexRay-Netzwerkmanagements an der Lebenslinie von <code>FrNm</code>.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li>Aufruf: <code>FrNm_Init(nmConfigPtr)</code> (synchroner Funktionsaufruf mit Konfigurationszeiger).</li>\n<li>Rückkehr: <code>FrNm_Init()</code> (Rückkehr-Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>EcuM</code> ruft während der BSW-Initialisierungsphase synchron die Funktion <code>FrNm_Init(nmConfigPtr)</code> am Modul <code>FrNm</code> auf.</li>\n<li><code>FrNm</code> aktiviert den internen Ausführungsfokus, verarbeitet die übergebene Konfiguration <code>nmConfigPtr</code> und etabliert den Ausgangszustand <code>Bus Sleep Mode</code>.</li>\n<li>Mit Abschluss der Initialisierungslogik kehrt die Steuerung über den Rückkehrpfad <code>FrNm_Init()</code> synchron an den <code>EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Initialisierung von <code>FrNm</code> wird durch den <code>EcuM</code> angestoßen (typischerweise im Rahmen der BSW-Init-Sequenzen/Init-Listen).</li>\n<li>Als initialer Zustand nach Aufruf von <code>FrNm_Init</code> ist <code>Bus Sleep Mode</code> vorgeschrieben.</li>\n<li>Die Übergabe der Konfiguration erfolgt zwingend über den Zeiger <code>nmConfigPtr</code>.</li>\n</ul>"}, {"id": "FIG-888ff8600feab907", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Initialisierungsablaufs des FlexRay-Netzwerkmanagements im Kontext der AUTOSAR Classic Platform (ECU State Management / Communication Stack). Dargestellt ist die synchrone Initialisierungssequenz zwischen dem ECU State Manager (<code>EcuM</code>) und dem BSW-Modul <code>FrNm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lebenslinien:</strong></li>\n<li><code>«module» EcuM</code>: ECU State Manager als zentrale Zustands- und Startsteuerungsinstanz der Basissoftware (Aufrufer).</li>\n<li><code>«module» FrNm</code>: FlexRay-spezifisches Netzwerkmanagement-Modul (Aufgerufener / Zielinstanz).</li>\n<li><strong>Zustandssymbol:</strong></li>\n<li><code>Bus Sleep Mode</code>: Zielzustand des FlexRay-Netzwerkmanagements an der Lebenslinie von <code>FrNm</code>.</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li>Aufruf: <code>FrNm_Init(nmConfigPtr)</code> (synchroner Funktionsaufruf mit Konfigurationszeiger).</li>\n<li>Rückkehr: <code>FrNm_Init()</code> (Rückkehr-Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>EcuM</code> ruft während der BSW-Initialisierungsphase synchron die Funktion <code>FrNm_Init(nmConfigPtr)</code> am Modul <code>FrNm</code> auf.</li>\n<li><code>FrNm</code> aktiviert den internen Ausführungsfokus, verarbeitet die übergebene Konfiguration <code>nmConfigPtr</code> und etabliert den Ausgangszustand <code>Bus Sleep Mode</code>.</li>\n<li>Mit Abschluss der Initialisierungslogik kehrt die Steuerung über den Rückkehrpfad <code>FrNm_Init()</code> synchron an den <code>EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Initialisierung von <code>FrNm</code> wird durch den <code>EcuM</code> angestoßen (typischerweise im Rahmen der BSW-Init-Sequenzen/Init-Listen).</li>\n<li>Als initialer Zustand nach Aufruf von <code>FrNm_Init</code> ist <code>Bus Sleep Mode</code> vorgeschrieben.</li>\n<li>Die Übergabe der Konfiguration erfolgt zwingend über den Zeiger <code>nmConfigPtr</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-52050a72c7f4a6b1", "to": "FIG-19a9027f6b6b5f5e", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-19a9027f6b6b5f5e", "to": "FIG-36369ccde3969e27", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-36369ccde3969e27", "to": "FIG-3e72ef664d858b20", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Aufrufende Entität geändert: Die Lebenslinie <code>«module» Nm</code> wurde durch <code>«module» EcuM</code> ersetzt; dem Modulsymbol des EcuM wurde ein Dekorationselement beigefügt.</li>\n</ul>"}, {"from": "FIG-3e72ef664d858b20", "to": "FIG-32edec8e1dd1e51c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-32edec8e1dd1e51c", "to": "FIG-888ff8600feab907", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
